public static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){
    if (str == null || suffix == null) {
        return null;
    }

    int strLength = str.length();
    int suffixLength = suffix.length();

    if (suffixLength > strLength) {
        return false;
    }

    int offset = strLength - suffixLength;

    if (!ignoreCase) {
        return str.regionMatches(offset, suffix);
    } else {
        return str.regionMatchesIgnoreCase(offset, suffix);
    }
}

